// Общее для «устаревший чанк → автозагрузка новой версии» (#4f5e3a, specs/stale-chunk-reload.md).
// Гость, прод, только просмотр: не-GET обрываются. SW блокируется в тестах (serviceWorkers: 'block').
// Чанк калькулятора ищется по запросу /assets/Calculator-<hash>.js — хэш не фиксирован.
// Экран «טוענים את הגרסה החדשה של האתר» живёт доли секунды до перезагрузки — MutationObserver пишет факт в sessionStorage
// (переживает перезагрузку вкладки); qa:saw-loading — пути, где был текст, qa:saw-error — был «משהו השתבש».
import { expect, BrowserContext, Page, Request } from '@playwright/test';

export const LOAD = { timeout: 30_000 };
export const LOADING_TEXT = 'טוענים את הגרסה החדשה של האתר';
export const ERROR_TEXT = 'משהו השתבש';
export const CALC_H1 = 'מחשבון כדאיות רכישת עסק';
export const CALC_CHUNK = /\/assets\/Calculator-[^/?]+\.js(\?.*)?$/;
export const DEVICES = ['@desktop', '@android'] as const;

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export async function prepare(context: BrowserContext) {
  await context.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  await context.addInitScript(
    ([loading, error]) => {
      try {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
        localStorage.setItem('b4s_install_prompt_dismissed_at', String(Date.now()));
      } catch {}
      const check = () => {
        const t = document.body ? document.body.innerText : '';
        try {
          if (t.includes(loading)) {
            const seen = sessionStorage.getItem('qa:saw-loading') || '';
            if (!seen.includes(location.pathname + ';')) sessionStorage.setItem('qa:saw-loading', seen + location.pathname + ';');
          }
          if (t.includes(error)) sessionStorage.setItem('qa:saw-error', '1');
        } catch {}
      };
      new MutationObserver(check).observe(document, { childList: true, subtree: true, characterData: true });
    },
    [LOADING_TEXT, ERROR_TEXT],
  );
}

export type ChunkMode = '404-once' | 'html-once' | '404-always';

/** Перехват чанка калькулятора. Возвращает счётчик запросов чанка. */
export async function breakCalculatorChunk(page: Page, mode: ChunkMode) {
  const ctl = { hits: 0 };
  await page.route(CALC_CHUNK, (route) => {
    ctl.hits++;
    const first = ctl.hits === 1;
    if (mode === '404-always' || (mode === '404-once' && first)) {
      return route.fulfill({ status: 404, contentType: 'text/plain', body: 'Not Found' });
    }
    if (mode === 'html-once' && first) {
      return route.fulfill({ status: 200, contentType: 'text/html', body: '<!doctype html><html lang="he"><head><title>Biz4Sale</title></head><body><div id="root"></div></body></html>' });
    }
    return route.fallback();
  });
  return ctl;
}

/** Навигации документа главного фрейма (перезагрузки) — считать после клика. */
export function trackDocumentNavigations(page: Page) {
  const docs: string[] = [];
  page.on('request', (r: Request) => {
    if (r.isNavigationRequest() && r.frame() === page.mainFrame()) docs.push(r.url());
  });
  return docs;
}

/** Открыть главную и перейти в калькулятор по ссылке (на телефоне ссылка может быть в меню «תפריט»). */
export async function openHome(page: Page) {
  await page.goto('/');
  await expect(page.locator('a[href="/calculator"]').first(), 'ссылка на калькулятор в DOM').toBeAttached(LOAD);
}

export async function clickCalculatorLink(page: Page) {
  const visible = page.locator('a[href="/calculator"]:visible').first();
  if ((await visible.count()) === 0) await page.getByRole('button', { name: 'תפריט' }).first().click();
  await page.locator('a[href="/calculator"]:visible').first().click();
}

export const ss = (page: Page, key: string) => page.evaluate((k) => sessionStorage.getItem(k), key);
